using LeadDesk;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.FileProviders;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

var builder = WebApplication.CreateBuilder(args);
builder.Configuration.AddJsonFile("appsettings.Local.json", optional: true, reloadOnChange: false).AddEnvironmentVariables().AddCommandLine(args);
var dataDirectory = Path.GetFullPath(builder.Configuration["DataDirectory"] ?? ".data");
Directory.CreateDirectory(dataDirectory); Directory.CreateDirectory(Path.Combine(dataDirectory, "keys"));
builder.Services.AddDataProtection().PersistKeysToFileSystem(new DirectoryInfo(Path.Combine(dataDirectory, "keys"))).SetApplicationName("NoLegalPaisa.LeadDesk");
builder.Services.AddDbContext<DeskDb>(o => { var cs = builder.Configuration["Database:ConnectionString"]!; if (builder.Configuration["Database:Provider"]?.Equals("MySql", StringComparison.OrdinalIgnoreCase) == true) o.UseMySQL(cs); else o.UseSqlite(cs); });
builder.Services.AddScoped<SettingsService>(); builder.Services.AddScoped<GeminiService>(); builder.Services.AddScoped<SignalService>(); builder.Services.AddHttpClient(); builder.Services.AddHostedService<MonitorWorker>();
builder.Services.ConfigureHttpJsonOptions(o => o.SerializerOptions.PropertyNamingPolicy = JsonNamingPolicy.CamelCase);
builder.WebHost.ConfigureKestrel(o => o.Limits.MaxRequestBodySize = 2_000_000);
var app = builder.Build();
string workspaceOwnerId;
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<DeskDb>();
    await Seed.Initialize(db);
    workspaceOwnerId = await Seed.WorkspaceOwner(db);
}
app.Use(async (ctx, next) =>
{
    ctx.Response.Headers["X-Content-Type-Options"] = "nosniff"; ctx.Response.Headers["Referrer-Policy"] = "strict-origin-when-cross-origin"; ctx.Response.Headers["X-Frame-Options"] = "DENY";
    ctx.Response.Headers["Content-Security-Policy"] = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'";
    if (ctx.Request.Path.StartsWithSegments("/api") || ctx.Request.Path.StartsWithSegments("/auth")) ctx.Response.Headers.CacheControl = "no-store";
    // A single shared workspace replaces account authentication. Existing ownership/history IDs remain intact.
    ctx.Items["WorkspaceOwnerId"] = workspaceOwnerId;
    try
    {
        if (ctx.Request.Path.StartsWithSegments("/api") && HttpMethods.IsPost(ctx.Request.Method) || ctx.Request.Path.StartsWithSegments("/api") && (HttpMethods.IsPut(ctx.Request.Method) || HttpMethods.IsDelete(ctx.Request.Method)))
        {
            if (ctx.Request.Headers["X-Lead-Desk"] != "1") throw new DeskError("Invalid request. Refresh the app and try again.", 403);
            var origin = ctx.Request.Headers.Origin.ToString(); var same = ctx.Request.Scheme + "://" + ctx.Request.Host; var dev = app.Environment.IsDevelopment() && origin == "http://127.0.0.1:5173";
            if (origin != "" && !origin.Equals(same, StringComparison.OrdinalIgnoreCase) && !dev) throw new DeskError("Cross-origin request rejected.", 403);
        }
        await next();
    }
    catch (DeskError e) { ctx.Response.StatusCode = e.Status; await ctx.Response.WriteAsJsonAsync(new { error = e.Message }); }
    catch (DbUpdateConcurrencyException) { ctx.Response.StatusCode = 409; await ctx.Response.WriteAsJsonAsync(new { error = "Someone else updated this lead. Refresh it before saving again." }); }
    catch (BadHttpRequestException) { ctx.Response.StatusCode = 400; await ctx.Response.WriteAsJsonAsync(new { error = "The request is invalid or too large." }); }
    catch (Exception e) { app.Logger.LogError("Request failed: {Type}", e.GetType().Name); ctx.Response.StatusCode = 500; await ctx.Response.WriteAsJsonAsync(new { error = "The server could not finish this action. Check the server logs and try again." }); }
});
app.MapGet("/api/health", () => new { status = "ok", version = "1.0.0" });
var leadGate = new SemaphoreSlim(1, 1);
app.MapGet("/api/workspace", async (HttpContext c, DeskDb db) => new { user = Security.Public(await c.Staff(db)), access = "open" });
app.MapGet("/auth/linkedin/callback", LinkedInOAuth.Callback);
var api = app.MapGroup("/api");
api.AddEndpointFilter(async (context, next) => { await context.HttpContext.Staff(context.HttpContext.RequestServices.GetRequiredService<DeskDb>()); return await next(context); });
api.MapGet("/staff", async (DeskDb db) => await db.Staff.Select(s => new { s.Id, s.Name, s.Email, s.Role, s.Active }).ToListAsync());
api.MapPost("/staff", async (StaffRequest i, HttpContext c, DeskDb db) => { var actor = await c.Admin(db); ValidatePerson(i.Name, i.Email); var email = Security.Email(i.Email, true); if (await db.Staff.AnyAsync(x => x.Email == email)) throw new DeskError("That email is already registered.", 409); var s = new Staff { Name = i.Name.Trim(), Email = email, Role = "Staff" }; db.Staff.Add(s); Leads.Audit(db, actor.Id, "Added team member", detail: s.Name); await db.SaveChangesAsync(); return Results.Ok(Security.Public(s)); });
api.MapPost("/staff/{id}/active", async (string id, Dictionary<string, bool> input, HttpContext c, DeskDb db) => { var actor = await c.Admin(db); if (id == actor.Id) throw new DeskError("The workspace owner must remain active."); var s = await db.Staff.FindAsync(id) ?? throw new DeskError("Team member not found.", 404); s.Active = input.GetValueOrDefault("active"); Leads.Audit(db, actor.Id, s.Active ? "Activated team member" : "Deactivated team member", detail: s.Name); await db.SaveChangesAsync(); return Results.Ok(Security.Public(s)); });
api.MapGet("/categories", async (DeskDb db) => { string[] order = ["general", "virtual-counsel", "protection", "exit", "closure", "trademark", "dpdp", "contracts", "funded", "professionals"]; var list = await db.Categories.ToListAsync(); return list.OrderBy(c => Array.IndexOf(order, c.Id) < 0 ? 100 : Array.IndexOf(order, c.Id)).ThenBy(c => c.Name); });
api.MapPost("/categories", async (Category category, HttpContext c, DeskDb db) => { var actor = await c.Admin(db); if (string.IsNullOrWhiteSpace(category.Name) || category.Name.Length > 120) throw new DeskError("Enter a category name up to 120 characters."); category.Id = Guid.NewGuid().ToString(); db.Categories.Add(category); Leads.Audit(db, actor.Id, "Added category", detail: category.Name); await db.SaveChangesAsync(); return Results.Ok(category); });
api.MapGet("/leads", async (bool? trash, DeskDb db) => await db.Leads.Include(x => x.Checks).Where(x => trash == true ? x.DeletedAt != null : x.DeletedAt == null).OrderByDescending(x => x.FitScore).ThenByDescending(x => x.CreatedAt).ToListAsync());
api.MapGet("/leads/{id}", async (string id, DeskDb db) => await Leads.Get(db, id));
api.MapPost("/leads", async (LeadInput i, HttpContext c, DeskDb db, SettingsService settings) =>
{
    var actor = await c.Staff(db); Leads.Validate(i); await ValidateLeadReferences(i, actor, db); await leadGate.WaitAsync(); try { var all = await db.Leads.Where(x => x.DeletedAt == null).ToListAsync(); if (all.Any(l => Leads.Duplicate(l, i))) throw new DeskError("This person is already in your pipeline.", 409); var l = new Lead(); Leads.Apply(l, i with { OwnerId = i.OwnerId == "" ? actor.Id : i.OwnerId }, actor.Id, await settings.Get("targetCities")); db.Leads.Add(l); Leads.Audit(db, actor.Id, "Added lead", l.Id, l.Name); await db.SaveChangesAsync(); return Results.Ok(l); } finally { leadGate.Release(); }
});
api.MapPut("/leads/{id}", async (string id, LeadInput i, HttpContext c, DeskDb db, SettingsService settings) =>
{
    var actor = await c.Staff(db); Leads.Validate(i); var l = await Leads.Get(db, id); Leads.Editable(actor, l); await ValidateLeadReferences(i, actor, db); if (i.Version != l.Version) throw new DeskError("This lead changed since you opened it. Close and reopen it before saving.", 409);
    await leadGate.WaitAsync(); try { var all = await db.Leads.Where(x => x.DeletedAt == null && x.Id != id).ToListAsync(); if (all.Any(other => Leads.Duplicate(other, i))) throw new DeskError("These contact details already belong to another lead.", 409); var old = l.Stage; Leads.Apply(l, i, actor.Id, await settings.Get("targetCities")); l.Version++; Leads.Audit(db, actor.Id, old != l.Stage ? $"Moved to {l.Stage}" : "Updated lead", l.Id); await db.SaveChangesAsync(); return Results.Ok(l); } finally { leadGate.Release(); }
});
api.MapPost("/leads/import", async (List<LeadInput> items, HttpContext c, DeskDb db, SettingsService settings) =>
{
    var actor = await c.Staff(db); if (items.Count == 0 || items.Count > 500) throw new DeskError("Import between 1 and 500 leads at a time."); foreach (var i in items) { Leads.Validate(i); await ValidateLeadReferences(i, actor, db); }
    var cities = await settings.Get("targetCities"); await leadGate.WaitAsync(); try { var existing = await db.Leads.Where(x => x.DeletedAt == null).ToListAsync(); int imported = 0, duplicates = 0; foreach (var i in items) { if (existing.Any(l => Leads.Duplicate(l, i))) { duplicates++; continue; } var l = new Lead(); Leads.Apply(l, i with { OwnerId = i.OwnerId == "" ? actor.Id : i.OwnerId, Approved = false }, actor.Id, cities); existing.Add(l); db.Leads.Add(l); Leads.Audit(db, actor.Id, "Imported lead", l.Id); imported++; } await db.SaveChangesAsync(); return Results.Ok(new { imported, duplicates }); } finally { leadGate.Release(); }
});
api.MapDelete("/leads/{id}", async (string id, HttpContext c, DeskDb db) => { var actor = await c.Staff(db); var l = await Leads.Get(db, id); Leads.Editable(actor, l); l.DeletedAt = DateTime.UtcNow; l.Version++; Leads.Audit(db, actor.Id, "Moved lead to trash", id); await db.SaveChangesAsync(); return Results.Ok(new { ok = true }); });
api.MapPost("/leads/{id}/restore", async (string id, HttpContext c, DeskDb db) => { var actor = await c.Staff(db); var l = await Leads.Get(db, id, true); Leads.Editable(actor, l); if (l.DeletedAt == null) throw new DeskError("This lead is already active."); var input = new LeadInput(Name: l.Name, Company: l.Company, LinkedInUrl: l.LinkedInUrl, Email: l.Email); var all = await db.Leads.Where(x => x.DeletedAt == null).ToListAsync(); if (all.Any(x => Leads.Duplicate(x, input))) throw new DeskError("A matching lead is already active. Review it before restoring.", 409); l.DeletedAt = null; l.Version++; Leads.Audit(db, actor.Id, "Restored lead", id); await db.SaveChangesAsync(); return Results.Ok(new { ok = true }); });
api.MapDelete("/leads/{id}/purge", async (string id, HttpContext c, DeskDb db) => { var actor = await c.Admin(db); var l = await Leads.Get(db, id, true); if (l.DeletedAt == null) throw new DeskError("Move this lead to trash before permanently deleting it."); db.OutreachLog.RemoveRange(await db.OutreachLog.Where(x => x.LeadId == id).ToListAsync()); db.AuditLog.RemoveRange(await db.AuditLog.Where(x => x.LeadId == id).ToListAsync()); db.Leads.Remove(l); Leads.Audit(db, actor.Id, "Permanently deleted a lead and its related history"); await db.SaveChangesAsync(); return Results.Ok(new { ok = true }); });
api.MapGet("/leads/{id}/history", async (string id, DeskDb db) => { await Leads.Get(db, id, true); return new { audit = await db.AuditLog.Where(x => x.LeadId == id).OrderByDescending(x => x.At).ToListAsync(), outreach = await db.OutreachLog.Where(x => x.LeadId == id).OrderByDescending(x => x.SentAt).ToListAsync() }; });
api.MapPost("/leads/{id}/outreach", async (string id, OutreachInput i, HttpContext c, DeskDb db, SettingsService settings) =>
{
    var actor = await c.Staff(db); var l = await Leads.Get(db, id); Leads.Editable(actor, l); if (!l.Approved) throw new DeskError("Review and approve this lead before recording outreach."); if (l.DoNotContact) throw new DeskError("This lead is marked Do not contact."); if (l.IsSample) throw new DeskError("Sample leads cannot be contacted. Add a real lead to record outreach.");
    if (!new[] { "LinkedIn invite", "LinkedIn message", "Email", "Call" }.Contains(i.Channel) || string.IsNullOrWhiteSpace(i.Message) || i.Message.Length > 10000 || i.Subject.Length > 250) throw new DeskError("Choose a channel and enter the message or call notes (up to 10,000 characters).");
    await leadGate.WaitAsync(); try { if (i.Channel == "LinkedIn invite") { var day = DateTime.UtcNow.Date; var count = await db.OutreachLog.CountAsync(x => x.StaffId == actor.Id && x.Channel == "LinkedIn invite" && x.SentAt >= day); var limit = int.Parse(await settings.Get("inviteLimit")); if (count >= limit) throw new DeskError("Your daily recorded invitation limit has been reached.", 429); } var o = new Outreach { LeadId = id, StaffId = actor.Id, Channel = i.Channel, Subject = i.Subject, Message = i.Message }; db.OutreachLog.Add(o); if (l.Stage is "New" or "Qualified") l.Stage = "Contacted"; l.FollowUpAt = i.FollowUpAt?.ToUniversalTime(); l.Version++; l.UpdatedAt = DateTime.UtcNow; Leads.Audit(db, actor.Id, "Recorded " + i.Channel, id); await db.SaveChangesAsync(); return Results.Ok(o); } finally { leadGate.Release(); }
});
api.MapGet("/export", async (DeskDb db) => { var rows = await db.Leads.Where(x => x.DeletedAt == null).ToListAsync(); string Cell(string? v) { v ??= ""; if (v.Length > 0 && "=+-@\t\r".Contains(v[0])) v = "'" + v; return "\"" + v.Replace("\"", "\"\"") + "\""; } var text = "Name,Job Title,Company,City,LinkedIn URL,Email,Category,Signal,Source,Source URL,Stage,Follow Up,Notes\r\n" + string.Join("\r\n", rows.Select(l => string.Join(',', new[] { l.Name, l.Title, l.Company, l.City, l.LinkedInUrl, l.Email, l.CategoryId, l.Signal, l.Source, l.SourceUrl, l.Stage, l.FollowUpAt?.ToString("O"), l.Notes }.Select(Cell)))); return Results.File(Encoding.UTF8.GetBytes("\uFEFF" + text), "text/csv; charset=utf-8", "nolegalpaisa-leads.csv"); });
api.MapGet("/overview", async (HttpContext c, DeskDb db, SettingsService settings) => { var id = c.UserId(); var leads = await db.Leads.Where(x => x.DeletedAt == null).ToListAsync(); var day = DateTime.UtcNow.Date; var retention = int.Parse(await settings.Get("retentionDays")); var usage = await db.AiUsage.Where(x => x.At >= day).ToListAsync(); return new { total = leads.Count, hot = leads.Count(l => l.FitScore >= 70 && l.Stage != "Won" && l.Stage != "Lost"), due = leads.Count(l => l.FollowUpAt <= DateTime.UtcNow && l.Stage != "Won" && l.Stage != "Lost"), won = leads.Count(l => l.Stage == "Won"), invites = await db.OutreachLog.CountAsync(x => x.StaffId == id && x.Channel == "LinkedIn invite" && x.SentAt >= day), inviteLimit = int.Parse(await settings.Get("inviteLimit")), sampleCount = leads.Count(l => l.IsSample), retentionDue = leads.Count(l => l.CreatedAt < DateTime.UtcNow.AddDays(-retention)), stages = Leads.Stages.Select(stage => new { stage, count = leads.Count(l => l.Stage == stage) }), aiRequests = usage.Count, aiTokens = usage.Sum(x => x.InputTokens + x.OutputTokens), aiLimit = int.Parse(await settings.Get("aiDailyLimit")), outreach = await db.OutreachLog.CountAsync(), meetings = leads.Count(l => l.Stage == "Meeting") }; });
api.MapGet("/activity", async (DeskDb db) => await db.AuditLog.OrderByDescending(x => x.At).Take(200).ToListAsync());
api.MapGet("/outreach", async (DeskDb db) => await db.OutreachLog.OrderByDescending(x => x.SentAt).Take(200).ToListAsync());
api.MapGet("/ai/usage", async (DeskDb db) => await db.AiUsage.OrderByDescending(x => x.At).Take(100).ToListAsync());
api.MapGet("/settings", async (HttpContext c, DeskDb db, SettingsService s) => { await c.Admin(db); return await s.Public(); });
api.MapPut("/settings", async (Dictionary<string, string> input, HttpContext c, DeskDb db, SettingsService s) =>
{
    var actor = await c.Admin(db); foreach (var (key, value) in input) { if (!SettingsService.Defaults.ContainsKey(key) && !SettingsService.Secrets.Contains(key)) throw new DeskError("Unknown setting: " + key); if (value.Length > 5000) throw new DeskError("A setting is too long."); if (key is "inviteLimit" or "aiDailyLimit" or "retentionDays") { if (!int.TryParse(value, out var n) || n < 1 || n > (key == "retentionDays" ? 3650 : 1000)) throw new DeskError("Enter a valid positive limit."); } if (key == "linkedinCallback" && (!Uri.TryCreate(value, UriKind.Absolute, out var u) || u.Scheme != "https" || u.AbsolutePath != "/auth/linkedin/callback" || u.Query != "" || u.Fragment != "")) throw new DeskError("The callback must be an HTTPS URL ending in /auth/linkedin/callback, without query parameters."); if (key is "companyUrl" or "senderProfile") Leads.Url(value); if (key == "geminiModel" && !System.Text.RegularExpressions.Regex.IsMatch(value, @"^gemini-[a-zA-Z0-9.\-]+$")) throw new DeskError("Enter a valid Gemini model identifier."); }
    foreach (var (key, value) in input) if (!SettingsService.Secrets.Contains(key) || value != "") await s.Set(key, value); if (input.ContainsKey("targetCities")) { var all = await db.Leads.Include(x => x.Checks).ToListAsync(); foreach (var l in all) { Leads.Score(l, input["targetCities"]); l.Version++; } }
    Leads.Audit(db, actor.Id, "Updated workspace settings"); await db.SaveChangesAsync(); return Results.Ok(await s.Public());
});
api.MapDelete("/settings/secrets/{key}", async (string key, HttpContext c, DeskDb db, SettingsService s) => { var actor = await c.Admin(db); if (!SettingsService.Secrets.Contains(key)) throw new DeskError("Unknown secret."); await s.Set(key, ""); Leads.Audit(db, actor.Id, "Removed integration credential", detail: key); await db.SaveChangesAsync(); return Results.Ok(new { ok = true }); });
api.MapGet("/integrations", async (HttpContext c, DeskDb db, SettingsService s) => { var a = await db.LinkedInAccounts.FindAsync(c.UserId()); return new { geminiConfigured = await s.Get("geminiKey") != "", geminiModel = await s.Get("geminiModel"), linkedinConfigured = await s.Get("linkedinClientId") != "" && await s.Get("linkedinClientSecret") != "", linkedin = a == null ? null : new { name = a.Name, email = a.Email, expiresAt = a.ExpiresAt, expired = a.ExpiresAt <= DateTime.UtcNow }, braveConfigured = await s.Get("braveKey") != "", callback = await s.Get("linkedinCallback") }; });
api.MapPost("/integrations/linkedin/start", async (HttpContext c, DeskDb db, SettingsService s, IDataProtectionProvider p) => new { url = await LinkedInOAuth.Start(c, db, s, p) });
api.MapDelete("/integrations/linkedin", async (HttpContext c, DeskDb db) => { var a = await db.LinkedInAccounts.FindAsync(c.UserId()); if (a != null) { db.LinkedInAccounts.Remove(a); Leads.Audit(db, c.UserId(), "Disconnected LinkedIn locally"); await db.SaveChangesAsync(); } return Results.Ok(new { ok = true }); });
api.MapPost("/discovery", (SearchCriteria criteria) => Discovery.Links(criteria));
api.MapGet("/searches", async (DeskDb db) => await db.Searches.ToListAsync());
api.MapPost("/searches", async (SearchInput i, HttpContext c, DeskDb db) => { if (string.IsNullOrWhiteSpace(i.Name) || i.Name.Length > 120) throw new DeskError("Give this search a name up to 120 characters."); var s = new SavedSearch { StaffId = c.UserId(), Name = i.Name, Criteria = JsonSerializer.Serialize(i.Criteria), Monitor = i.Monitor }; db.Searches.Add(s); await db.SaveChangesAsync(); return Results.Ok(s); });
api.MapDelete("/searches/{id}", async (string id, HttpContext c, DeskDb db) => { var actor = await c.Staff(db); var s = await db.Searches.FindAsync(id) ?? throw new DeskError("Search not found.", 404); if (s.StaffId != actor.Id && actor.Role != "Admin") throw new DeskError("This search belongs to another team member.", 403); db.Signals.RemoveRange(await db.Signals.Where(x => x.SearchId == id).ToListAsync()); db.Searches.Remove(s); await db.SaveChangesAsync(); return Results.Ok(new { ok = true }); });
api.MapPost("/searches/{id}/run", async (string id, DeskDb db, SignalService signals) => { var s = await db.Searches.FindAsync(id) ?? throw new DeskError("Search not found.", 404); if (s.LastRunAt > DateTime.UtcNow.AddMinutes(-2)) throw new DeskError("Please wait two minutes between runs.", 429); return Results.Ok(new { found = await signals.Run(s) }); });
api.MapGet("/signals", async (DeskDb db) => await db.Signals.OrderByDescending(x => x.At).Take(200).ToListAsync());
api.MapPost("/signals/{id}/review", async (string id, DeskDb db) => { var s = await db.Signals.FindAsync(id) ?? throw new DeskError("Signal not found.", 404); s.Reviewed = true; await db.SaveChangesAsync(); return Results.Ok(new { ok = true }); });
api.MapPost("/retention/archive", async (HttpContext c, DeskDb db, SettingsService settings) => { var actor = await c.Admin(db); var before = DateTime.UtcNow.AddDays(-int.Parse(await settings.Get("retentionDays"))); var all = await db.Leads.Where(x => x.DeletedAt == null && x.CreatedAt < before).ToListAsync(); foreach (var l in all) { l.DeletedAt = DateTime.UtcNow; l.Version++; Leads.Audit(db, actor.Id, "Archived under retention policy", l.Id); } await db.SaveChangesAsync(); return Results.Ok(new { archived = all.Count }); });
api.MapPost("/samples", async (HttpContext c, DeskDb db, SettingsService settings) => { var actor = await c.Admin(db); if (await db.Leads.AnyAsync(x => x.IsSample)) throw new DeskError("Sample leads are already loaded.", 409); var cities = await settings.Get("targetCities"); var data = new[] { new LeadInput(Name: "Aarav Mehta", Title: "Founder & CEO", Company: "Example Fintech", City: "Mumbai", CategoryId: "dpdp", Signal: "Hiring", Evidence: "Fictional sample: hiring a privacy officer", Stage: "Qualified", IsSample: true, FollowUpAt: DateTime.UtcNow.AddDays(-1)), new LeadInput(Name: "Nisha Rao", Title: "Head of Operations", Company: "Example Consumer Co.", City: "Bengaluru", CategoryId: "contracts", Signal: "New company", Stage: "New", IsSample: true), new LeadInput(Name: "Kabir Shah", Title: "Co-founder", Company: "Example Cloud", City: "Pune", CategoryId: "funded", Signal: "Raised funding", Stage: "Meeting", IsSample: true, FollowUpAt: DateTime.UtcNow.AddDays(2)), new LeadInput(Name: "Isha Kapoor", Title: "CFO", Company: "Example Retail", City: "Delhi", CategoryId: "protection", Signal: "Asked for help", Stage: "Replied", IsSample: true) }; foreach (var i in data) { var l = new Lead(); Leads.Apply(l, i with { OwnerId = actor.Id, Source = "Fictional sample data" }, actor.Id, cities); db.Leads.Add(l); } Leads.Audit(db, actor.Id, "Loaded fictional sample leads"); await db.SaveChangesAsync(); return Results.Ok(new { added = data.Length }); });
api.MapPost("/ai/test", async (HttpContext c, GeminiService ai) => await ai.Generate(c.UserId(), "connection test", "Return the status string ok.", "Return ok.", GeminiService.Schema(new() { { "status", GeminiService.Str } })));
api.MapPost("/ai/build-search", async (AiInput i, HttpContext c, GeminiService ai) => { if (string.IsNullOrWhiteSpace(i.Text)) throw new DeskError("Describe the people you want to find."); return await ai.Generate(c.UserId(), "build search", "Convert the user's request into comma-separated search fields. Do not claim that any people were found. If a location is unspecified use India.", i.Text, GeminiService.Schema(new() { { "titles", GeminiService.Str }, { "keywords", GeminiService.Str }, { "phrases", GeminiService.Str }, { "jobs", GeminiService.Str }, { "city", GeminiService.Str }, { "exclude", GeminiService.Str } })); });
api.MapPost("/ai/extract-leads", async (AiInput i, HttpContext c, GeminiService ai) => { if (string.IsNullOrWhiteSpace(i.Text)) throw new DeskError("Paste the source text first."); var row = GeminiService.Schema(new() { { "name", GeminiService.Str }, { "title", GeminiService.Str }, { "company", GeminiService.Str }, { "city", GeminiService.Str }, { "linkedInUrl", GeminiService.Str }, { "email", GeminiService.Str }, { "evidence", GeminiService.Str } }); var result = await ai.Generate(c.UserId(), "extract leads", "Extract at most 50 identifiable people from the supplied text. Use only explicit facts; unknown values must be empty strings. Do not infer email addresses, profile URLs, buying signals or identities from job adverts. Exclude entries without an actual person's name. All rows will be reviewed by a human before import.", i.Text, GeminiService.Schema(new() { { "leads", new { type = "array", items = row } } })); if (result["leads"] is not JsonArray rows || rows.Count > 50) throw new DeskError("AI returned an invalid result. Nothing was imported.", 502); return result; });
api.MapPost("/ai/draft-message", async (AiInput i, HttpContext c, DeskDb db, SettingsService settings, GeminiService ai) => { var l = await Leads.Get(db, i.LeadId); if (l.DoNotContact || l.IsSample) throw new DeskError("Drafting is unavailable for sample leads and people marked Do not contact."); var cat = await db.Categories.FindAsync(l.CategoryId); return await ai.Generate(c.UserId(), "draft message", "Write a short, respectful, non-pushy outreach draft. Do not imply a prior relationship, promise outcomes, invent credentials or assert that a legal breach occurred. Mention a buying signal only if the supplied evidence explicitly supports it. For a LinkedIn invite use at most 200 characters in message. Return subject and message. A human must review the draft before sending.", JsonSerializer.Serialize(new { channel = i.Channel, sender = await settings.Get("senderName"), service = cat?.Name, l.Name, l.Title, l.Company, l.Evidence }), GeminiService.Schema(new() { { "subject", GeminiService.Str }, { "message", GeminiService.Str } })); });
var dist = Path.GetFullPath(Path.Combine(app.Environment.ContentRootPath, "../client/dist")); if (Directory.Exists(dist)) { var provider = new PhysicalFileProvider(dist); app.UseDefaultFiles(new DefaultFilesOptions { FileProvider = provider }); app.UseStaticFiles(new StaticFileOptions { FileProvider = provider }); app.MapFallback(async context => { if (context.Request.Path.StartsWithSegments("/api") || context.Request.Path.StartsWithSegments("/auth")) { context.Response.StatusCode = 404; await context.Response.WriteAsJsonAsync(new { error = "Endpoint not found." }); } else { context.Response.ContentType = "text/html"; await context.Response.SendFileAsync(Path.Combine(dist, "index.html")); } }); }
app.Run();

static void ValidatePerson(string name, string email) { if (string.IsNullOrWhiteSpace(name) || name.Length > 160) throw new DeskError("Enter a name up to 160 characters."); Security.Email(email, true); }
static async Task ValidateLeadReferences(LeadInput i, Staff actor, DeskDb db) { if (i.CategoryId != "" && !await db.Categories.AnyAsync(x => x.Id == i.CategoryId)) throw new DeskError("Choose an existing category."); if (i.OwnerId != "" && !await db.Staff.AnyAsync(x => x.Id == i.OwnerId && x.Active)) throw new DeskError("Choose an active lead owner."); if (actor.Role != "Admin" && i.OwnerId != "" && i.OwnerId != actor.Id) throw new DeskError("Only an administrator can assign leads to other staff.", 403); }
